package cli
import("encoding/json";"fmt";"io";"github.com/developmentconexus-ops/aurora_project/internal/application";"github.com/developmentconexus-ops/aurora_project/internal/domain/project")
func renderResult(out io.Writer,asJSON bool,v any)error{if asJSON{return json.NewEncoder(out).Encode(v)};switch r:=v.(type){case application.InitializeResult:_,err:=fmt.Fprintf(out,"Aurora initialized\nAurora ID: %s\nOwner: %s\nGeneration: %d\n",r.AuroraID,r.OwnerOperatorID,r.GoverningGeneration);return err;case application.InspectResult:_,err:=fmt.Fprintf(out,"Aurora ID: %s\nOwner: %s\nAuthority revision: %d\nGeneration: %d\nTrust: %s\n",r.AuroraID,r.OwnerOperatorID,r.CurrentAuthorityRevision,r.GoverningGeneration,r.TrustStatus);return err;case project.Project:_,err:=fmt.Fprintf(out,"Project created\nProject ID: %s\nLabel: %s\nObjective: %s\n",r.ProjectID,r.DisplayLabel,r.ObjectiveSummary);return err;case application.ProjectView:_,err:=fmt.Fprintf(out,"Project ID: %s\nLabel: %s\nObjective: %s\n",r.Project.ProjectID,r.Project.DisplayLabel,r.Project.ObjectiveSummary);if err!=nil{return err};if r.CurrentState==nil{_,err=fmt.Fprintln(out,"Current state: NONE");return err};_,err=fmt.Fprintf(out,"Current state revision: %d\nState kind: %s\nState summary: %s\n",r.CurrentState.Revision,r.CurrentState.State.Kind,r.CurrentState.State.Summary);if err!=nil{return err};if r.NextSafeAction!=nil{_,err=fmt.Fprintf(out,"Next safe action: %s\n",r.NextSafeAction.Decision)};return err;case project.ProjectStateRevision:_,err:=fmt.Fprintf(out,"State accepted\nProject ID: %s\nState revision: %d\nState kind: %s\nState summary: %s\n",r.ProjectID,r.Revision,r.State.Kind,r.State.Summary);return err;case application.AuthorityView:_,err:=fmt.Fprintf(out,"Authority state revision: %d\nGrants: %d\nRevalidation required: %t\n",r.State.Revision,len(r.State.Grants),r.State.RevalidationRequired);return err;case application.ExportResult:_,err:=fmt.Fprintf(out,"Export created\nExport ID: %s\nSHA-256: %s\nCreated at: %s\n",r.ExportID,r.PayloadSHA256,r.CreatedAt.Format("2006-01-02T15:04:05Z07:00"));return err;case application.RestoreResult:_,err:=fmt.Fprintf(out,"Restore complete\nExport ID: %s\nAurora ID: %s\nAuthority revision: %d\nGeneration: %d\nTrust: %s\n",r.ExportID,r.AuroraID,r.AuthorityStateRevision,r.GoverningGeneration,r.TrustStatus);return err;default:return fmt.Errorf("unsupported CLI result type %T",v)}}
